"use client";

import { useState, useMemo } from "react";
import { ChevronLeft, ChevronRight, Plus, X } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem } from "@/app/actions/task-actions";
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("agenda");

  // VERİLERİ GÜNLERE EŞLEŞTİRME (EN ÖNEMLİ KISIM)
  const taskMap = useMemo(() => {
    return initialTasks.reduce((acc: any, item) => {
      if (item.startDatetime) {
        // DB'den gelen tarihi UTC kayması olmadan yerel formatta alıyoruz
        const d = new Date(item.startDatetime);
        const dateKey = format(d, "yyyy-MM-dd");
        
        if (!acc[dateKey]) acc[dateKey] = [];
        acc[dateKey].push(item);
      }
      return acc;
    }, {});
  }, [initialTasks]);

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    const payload = {
      titel: title,
      documentType: type,
      datum: format(selectedDate, "yyyy-MM-dd"),
    };

    try {
      const res = await createCalendarItem(payload);
      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        router.refresh();
        // Veritabanı işleminin yansıması için kısa bir gecikme ile reload
        setTimeout(() => window.location.reload(), 300);
      } else {
        alert("Fout: " + res.error);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-10 relative">
      {/* HEADER */}
      <div className="flex justify-between items-center mb-10 border-b border-white/5 pb-8">
        <h1 className="text-5xl font-black text-white italic tracking-tighter uppercase">Temporal Grid</h1>
        <div className="flex items-center gap-4 bg-[#0a0e17] border border-white/10 p-2 rounded-xl text-white">
          <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-2 text-teal-500 hover:text-fuchsia-500 transition-colors cursor-pointer"><ChevronLeft size={24} /></button>
          <span className="text-lg font-bold w-48 text-center">{format(currentMonth, "MMMM yyyy", { locale: nl })}</span>
          <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-2 text-teal-500 hover:text-fuchsia-500 transition-colors cursor-pointer"><ChevronRight size={24} /></button>
        </div>
      </div>

      {/* TAKVİM IZGARASI */}
      <div className="bg-[#0a0e17]/80 border border-white/10 rounded-[32px] overflow-hidden shadow-2xl backdrop-blur-xl">
        <div className="grid grid-cols-7 bg-white/5 py-4 border-b border-white/10 text-center text-[10px] font-black text-teal-500/40 uppercase tracking-widest">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => <span key={d}>{d}</span>)}
        </div>
        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

            while (day <= endDate) {
              const dateKey = format(day, "yyyy-MM-dd");
              const dayTasks = taskMap[dateKey] || []; // Eşleşen görevleri bul
              const isCurrentMonth = isSameMonth(day, currentMonth);
              const isToday = isSameDay(day, new Date());
              const currentDay = day;

              days.push(
                <div 
                  key={day.toString()} 
                  onClick={() => setSelectedDate(currentDay)}
                  className={`min-h-[160px] border border-white/5 p-4 transition-all hover:bg-fuchsia-500/5 cursor-pointer relative group ${!isCurrentMonth ? "opacity-5 pointer-events-none" : "opacity-100"}`}
                >
                  <span className={`text-xs font-mono mb-2 block ${isToday ? "text-fuchsia-500 font-bold" : "text-teal-500/20"}`}>{format(day, "d")}</span>
                  
                  {/* VERİLERİN EKRANDA GÖSTERİLDİĞİ LİSTE */}
                  <div className="space-y-1">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} className={`text-[9px] px-2 py-1 truncate rounded border font-bold uppercase ${
                        t.description === 'agenda' || t.description === 'assignment' 
                        ? 'bg-blue-600/10 border-blue-500/30 text-blue-400' 
                        : 'bg-fuchsia-600/10 border-fuchsia-500/30 text-fuchsia-400'
                      }`}>
                        {t.title}
                      </div>
                    ))}
                  </div>
                  
                  <div className="absolute bottom-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Plus size={16} className="text-fuchsia-500" />
                  </div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {/* OVERLAY FORM */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#02040a]/90 backdrop-blur-md px-4">
          <div className="bg-[#0E153A] border border-fuchsia-500/40 p-10 rounded-[32px] w-full max-w-md shadow-2xl relative">
            <button onClick={() => setSelectedDate(null)} className="absolute top-6 right-6 text-white/20 hover:text-white cursor-pointer"><X size={28} /></button>
            <h3 className="text-fuchsia-500 font-black text-[10px] tracking-[0.4em] uppercase mb-2">Item Toevoegen</h3>
            <p className="text-2xl font-bold text-white italic mb-8">{format(selectedDate, "dd MMMM yyyy", { locale: nl })}</p>
            
            <div className="space-y-6">
              <input 
                autoFocus 
                value={title} onChange={(e) => setTitle(e.target.value)} 
                className="w-full bg-[#070B24] border border-white/10 p-5 text-white font-bold rounded-xl focus:border-fuchsia-500 outline-none" 
                placeholder="Titel..." 
              />
              <div className="grid grid-cols-2 gap-3">
                {['agenda', 'assignment', 'meeting', 'daily'].map(cat => (
                  <button key={cat} onClick={() => setType(cat)} className={`py-3 text-[10px] font-black uppercase border rounded-lg transition-all ${type === cat ? 'bg-fuchsia-600 border-fuchsia-600 text-white shadow-[0_0_15px_rgba(217,70,239,0.3)]' : 'bg-[#070B24] border-white/5 text-white/40'}`}>{cat}</button>
                ))}
              </div>
              <button 
                onClick={handleSave} 
                disabled={loading || !title} 
                className="w-full bg-white text-[#0E153A] font-black py-5 mt-4 hover:bg-fuchsia-500 hover:text-white transition-all uppercase text-xs tracking-widest rounded-xl disabled:opacity-20 shadow-xl"
              >
                {loading ? "Verwerken..." : "Bevestigen"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}