"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createNewTask(data: any) {
  try {
    const user = await prisma.user.findFirst();
    if (!user) return { success: false, error: "Gebruiker niet gevonden." };

    await prisma.task.create({
      data: {
        title: data.titel,
        description: JSON.stringify(data), 
        userId: user.id,
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Create Error:", error);
    return { success: false };
  }
}

export async function deleteTask(id: string) {
  try {
    await prisma.task.delete({
      where: { id },
    });
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Delete Error:", error);
    return { success: false };
  }
}

export async function updateTaskContent(id: string, fullData: any) {
  try {
    await prisma.task.update({
      where: { id },
      data: {
        description: JSON.stringify(fullData),
      },
    });
    return { success: true };
  } catch (error) {
    console.error("Update Error:", error);
    return { success: false };
  }
}

export async function createCalendarItem(data: any) {
  try {
    const user = await prisma.user.findFirst();
    if (!user) return { success: false, error: "Gebruiker niet gevonden." };

    // Tarihi günün başlangıcı (00:00:00) ve bitişi (23:59:59) olarak ayarla
    const startDate = new Date(data.datum);
    startDate.setHours(0, 0, 0, 0);

    const endDate = new Date(data.datum);
    endDate.setHours(23, 59, 59, 999);

    const newItem = await prisma.calender.create({
      data: {
        userId: user.id,
        title: data.titel,
        description: data.documentType, 
        startDatetime: startDate, // DB'deki DateTime alanı
        endDatetime: endDate,     // DB'deki DateTime alanı
      },
    });

    revalidatePath("/calendar");
    return { success: true, data: newItem };
  } catch (error: any) {
    console.error("DB Error:", error);
    return { success: false, error: error.message };
  }
}